import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 2D convolution (groups == 1, square kernel).
// Each thread block computes a TILE_H x TILE_W tile of outputs for one
// (batch, out_channel). The input halo tile for every input channel is
// loaded cooperatively into shared memory and reused for all K*K taps.
template <typename T, int TILE_H, int TILE_W, int THREADS>
__global__ void conv2d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int C, int H, int Win,
    int OC, int K,
    int stride, int padding, int dilation,
    int Hout, int Wout,
    int tiles_per_row)
{
  extern __shared__ char smem_raw[];
  T* smem = reinterpret_cast<T*>(smem_raw);

  const int tid     = threadIdx.x;
  const int n       = blockIdx.z;
  const int oc      = blockIdx.y;
  const int tile_id = blockIdx.x;

  const int tile_oh = tile_id / tiles_per_row;
  const int tile_ow = tile_id - tile_oh * tiles_per_row;
  const int oh0 = tile_oh * TILE_H;
  const int ow0 = tile_ow * TILE_W;

  // Input (halo) tile dimensions needed for this output tile
  const int IN_H = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
  const int IN_W = (TILE_W - 1) * stride + (K - 1) * dilation + 1;

  // Global memory strides (NCHW / OIHW contiguous)
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWo = (int64_t)C * K * K;
  const int64_t sWc = (int64_t)K * K;

  // CuTe views of the global tensors
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                        make_shape(C, H, Win),
                        make_stride(sXc, sXh, Int<1>{}));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                        make_shape(OC, Hout, Wout),
                        make_stride(sYc, sYh, Int<1>{}));

  auto mW = make_tensor(make_gmem_ptr(Wt),
                        make_shape(OC, C, K, K),
                        make_stride(sWo, sWc, (int64_t)K, Int<1>{}));

  // CuTe view of the shared-memory input halo tile (row-major)
  auto sX = make_tensor(make_smem_ptr(smem),
                        make_shape(IN_H, IN_W),
                        make_stride(IN_W, Int<1>{}));

  // Each thread owns exactly one output pixel of the tile
  const int th = tid / TILE_W;
  const int tw = tid - th * TILE_W;
  const int oh = oh0 + th;
  const int ow = ow0 + tw;
  const bool valid_out = (oh < Hout) && (ow < Wout);

  float acc = (B != nullptr) ? (float)B[oc] : 0.0f;

  const int in_base_h = oh0 * stride - padding;
  const int in_base_w = ow0 * stride - padding;

  for (int ic = 0; ic < C; ++ic) {
    __syncthreads();  // protect against overwriting smem still being read

    // Cooperative load of the input halo tile (zero padding out of bounds)
    for (int idx = tid; idx < IN_H * IN_W; idx += THREADS) {
      const int ih_l = idx / IN_W;
      const int iw_l = idx - ih_l * IN_W;
      const int ih = in_base_h + ih_l;
      const int iw = in_base_w + iw_l;
      T v = T(0);
      if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        v = mX(ic, ih, iw);
      }
      sX(ih_l, iw_l) = v;
    }
    __syncthreads();

    // Accumulate K*K taps from the shared tile
    if (valid_out) {
      const int ih_l0 = th * stride;
      const int iw_l0 = tw * stride;
      #pragma unroll 4
      for (int kh = 0; kh < K; ++kh) {
        const int ih_l = ih_l0 + kh * dilation;
        #pragma unroll 4
        for (int kw = 0; kw < K; ++kw) {
          const int iw_l = iw_l0 + kw * dilation;
          acc += (float)sX(ih_l, iw_l) * (float)mW(oc, ic, kh, kw);
        }
      }
    }
  }

  if (valid_out) {
    mY(oc, oh, ow) = static_cast<T>(acc);
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, C, K, K]");
  TORCH_CHECK(stride > 0 && dilation > 0 && padding >= 0,
              "invalid stride/padding/dilation");

  const int64_t N   = x.size(0);
  const int64_t C   = x.size(1);
  const int64_t H   = x.size(2);
  const int64_t Win = x.size(3);
  const int64_t OC  = w.size(0);
  const int64_t K   = w.size(2);
  TORCH_CHECK(w.size(1) == C, "w.size(1) must equal C");
  TORCH_CHECK(w.size(3) == K, "kernel must be square");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  const int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  constexpr int TILE_H  = 16;
  constexpr int TILE_W  = 16;
  constexpr int THREADS = TILE_H * TILE_W;  // 256

  const int tiles_per_col = (int)((Hout + TILE_H - 1) / TILE_H);
  const int tiles_per_row = (int)((Wout + TILE_W - 1) / TILE_W);

  const int IN_H = (TILE_H - 1) * stride + (int)((K - 1) * dilation) + 1;
  const int IN_W = (TILE_W - 1) * stride + (int)((K - 1) * dilation) + 1;
  const size_t smem_bytes = (size_t)IN_H * (size_t)IN_W * sizeof(float);

  dim3 block(THREADS);
  dim3 grid((unsigned)(tiles_per_col * tiles_per_row),
            (unsigned)OC,
            (unsigned)N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_tiled_kernel<float, TILE_H, TILE_W, THREADS>
      <<<grid, block, smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          b_ptr,
          y.data_ptr<float>(),
          (int)C, (int)H, (int)Win,
          (int)OC, (int)K,
          stride, padding, dilation,
          (int)Hout, (int)Wout,
          tiles_per_row);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_tiled_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution (square kernel, groups=1) implemented with a single
    cooperative tiled CuTe/CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        C_in = self.in_channels // self.groups
        self.weight = nn.Parameter(
            torch.empty(self.out_channels, C_in, self.kernel_size, self.kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        if self.bias is not None:
            fan_in = self.in_channels // self.groups * self.kernel_size * self.kernel_size
            bound = 1.0 / (fan_in ** 0.5) if fan_in > 0 else 0.0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.groups != 1 or not x.is_cuda or x.dtype != torch.float32:
            return F.conv2d(x, self.weight, self.bias, stride=self.stride,
                            padding=self.padding, dilation=self.dilation,
                            groups=self.groups)
        return self._ext.conv2d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

