  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWo = (int64_t)C * K * K;
  const int64_t sWc = (int64_t)K * K;

  // CuTe views of the global tensors
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                        make_shape(C, H, Win),
                        make_stride(sXc, sXh, Int<1>{}));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                        make_shape(OC, Hout, Wout),
                        make_stride(sYc, sYh, Int<1>{}));

  auto mW = make_tensor(make_gmem_ptr(Wt),
                        make_shape(OC, C, K, K),
                        make_stride(sWo, sWc, (int64_t)K, Int<1>{}));

  // CuTe view of the shared-memory input halo tile (row-major)
  auto sX = make_tensor(make_smem_ptr(smem),
                        make_shape(IN_H, IN_W),
                        make_stride(IN_W, Int<1>{}));

  // Each thread owns exactly one output pixel of the tile
  const int th = tid / TILE_W;
  const int tw = tid - th * TILE_W;
  const int oh = oh0 + th;
  const int ow = ow0 + tw;
  const bool valid_out = (oh < Hout) && (ow < Wout);

  float acc = (B != nullptr) ? (float)B[oc] : 0.0f;

  const int in_base_h = oh0 * stride - padding;
  const int in_base_w = ow0 * stride - padding;

  for (int ic = 0; ic < C; ++ic) {
    __syncthreads();  // protect against overwriting smem still being read

    // Cooperative load of the input halo tile (zero padding out of bounds)
    for (int idx = tid; idx < IN_H * IN_W; idx += THREADS) {
      const int ih_l = idx / IN_W;
      const int iw_l = idx - ih_l * IN_W;
      const int ih = in_base_h + ih_l;
      const int iw = in_base_w + iw_l;
      T v = T(0);
      if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        v = mX(ic, ih, iw);
      }
      sX(ih_l, iw_l) = v;
    }
    __syncthreads();

    // Accumulate K*K taps from the shared tile
    if (valid_out) {
      const int ih_l0 = th * stride;
      const int iw_l0 = tw * stride;
      #pragma unroll 4
      for (int kh = 0; kh < K; ++kh) {
        const int ih_l = ih_l0 + kh * dilation;
        #pragma unroll 4
        for (int kw = 0; kw < K; ++kw) {
          const int iw_l = iw_l0 + kw * dilation;
          acc += (float)sX(ih_l, iw_l) * (float)mW(oc, ic, kh, kw);
        }
      }
    }
  }

  if (valid_out) {
    mY(oc, oh, ow) = static_cast<T>(acc);
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, C, K, K]");
  TORCH_CHECK(stride > 0 && dilation > 0 && padding >= 0,
              "invalid stride/padding/dilation");

  const int64_t N   = x.size(0);
  const int64_t C   = x.size(1);
  const int64_t H   = x.size(2);
  const int64_t Win = x.size(3);
  const int64_t OC  = w.size(0);
  const int64_t K   = w.size(2);
  TORCH_CHECK(w.size(1) == C, "w.size(1) must equal C");
  TORCH_CHECK(w.size(3) == K, "kernel must be square");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  const int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  const int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  constexpr int TILE_H  = 16;
  constexpr int TILE_W  = 16;
  constexpr int THREADS = TILE_H * TILE_W;  // 256

  const int tiles_per_col = (int)((Hout + TILE_H - 1) / TILE_H);
  const int tiles_per_row = (int)((Wout + TILE_W - 1) / TILE_W);

  const int IN_H = (TILE_H - 1) * stride + (int)((K - 1) * dilation) + 1;
  const int IN_W = (TILE_W - 1) * stride + (int)((K - 1) * dilation) + 1;
  const size_t smem_bytes = (size_t)IN_H * (size_t)IN_W * sizeof(float);

  dim3 block(THREADS);
  dim3 grid((unsigned)(tiles_per_col * tiles_per_row),
            (unsigned)OC,
            (unsigned)N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_tiled_kernel<float, TILE_H, TILE_W, THREADS>
      <<<grid, block, smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          b_ptr,
          y.data_ptr<float>(),
          (int)C, (int)H, (int)Win,
          (int)OC, (int)K,
          stride, padding, dilation,
          (int)Hout, (int)Wout,
          tiles_per_row);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
